script:
frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm){
        if (frm.doc.excel_invoice_type == 'Completed Project') {
            frm.set_df_property('custom_handover_date', 'hidden', 0);
            frm.refresh_field('custom_handover_date');
            if(frm.doc.docstatus == 1){
               frm.set_df_property( 'excel_invoice_type', 'read_only', 1); 
               frm.refresh_field('excel_invoice_type');
            }

        } else {
            frm.set_df_property('custom_handover_date', 'hidden', 1); 
            frm.refresh_field('custom_handover_date');

        }

    },
    excel_invoice_type : function(frm){
         if (frm.doc.excel_invoice_type == 'Completed Project') {
            frm.set_df_property('custom_handover_date', 'hidden', 0);
            frm.refresh_field('custom_handover_date');
             if(frm.doc.docstatus == 1){
              frm.set_df_property( 'excel_invoice_type', 'read_only', 1); 
              frm.refresh_field('excel_invoice_type');
            }

        } else {
            frm.set_df_property('custom_handover_date', 'hidden', 1); 
            frm.refresh_field('custom_handover_date');

        }
    },
    validate: function(frm) {
        let today = frappe.datetime.nowdate();
        let handover_date = frm.doc.custom_handover_date;
        if (handover_date && handover_date < today) {
            frappe.msgprint(__('Handover Date cannot be earlier than today.'));
            frappe.validated = false;
        }
    }


});

frappe.ui.form.on('Payment Entry', {
    validate: function(frm) {
        const territory = frm.doc.excel_territory;
        console.log("Territory: ", territory);

        if (territory === "Corporate" || territory === "Tender") {
            let all_rows_valid = true; // Flag to track row validation status

            // Loop through all rows in the references child table
            frm.doc.references.forEach((reference, index) => {
                // Check if the outstanding_amount and allocated_amount are not equal
                if (flt(reference.outstanding_amount) !== flt(reference.allocated_amount)) {
                    // Check if outstanding_types is missing
                    if (!reference.outstanding_types) {
                        console.log(`Outstanding Types is missing for row ${index + 1}`);
                        frappe.msgprint(__('Outstanding Types must be filled for all rows with mismatched Outstanding Amount and Allocated Amount.'));
                        frm.fields_dict['references'].grid.get_field('outstanding_types').reqd = 1; // Make it required
                        all_rows_valid = false; // Mark as invalid
                    }
                }
            });

            // If any row is invalid, prevent form submission
            if (!all_rows_valid) {
                frappe.validated = false;
            }
        }
    },

    on_submit: function(frm) {
        // Loop through references and update related Sales Invoice
        if (frm.doc.references && frm.doc.references.length > 0) {
            frm.doc.references.forEach(reference => {
                if (reference.outstanding_types && reference.reference_name) {
                    frappe.call({
                        method: 'frappe.client.get',
                        args: {
                            doctype: 'Sales Invoice',
                            name: reference.reference_name // Get the Sales Invoice ID from reference_name
                        },
                        callback: function(r) {
                            if (r.message) {
                                // Update the Sales Invoice with the outstanding_types from the reference
                                const sales_invoice = r.message;
                                sales_invoice.custom_outstanding_types = reference.outstanding_types; // Update field

                                // Save the updated Sales Invoice
                                frappe.call({
                                    method: 'frappe.client.save',
                                    args: {
                                        doc: sales_invoice
                                    },
                                    callback: function(save_r) {
                                        if (save_r.message) {
                                            // console.log("Sales Invoice updated successfully!");
                                        } else {
                                            // console.log("Failed to update Sales Invoice.");
                                        }
                                    }
                                });
                            }
                        }
                    });
                }
            });
        }
    }
});
